import io,json,os,pathlib,re,secrets,shlex,subprocess,tarfile,tempfile,time

PROBE = r'''#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <signal.h>
volatile sig_atomic_t received=0;
static void handler(int value){received=value;}
int main(int argc,char **argv){
 if(argc>1 && !strcmp(argv[1],"args")){for(int i=2;i<argc;i++)printf("ARG_%d=%s\n",i-1,argv[i]);return 0;}
 if(argc>2 && !strcmp(argv[1],"file")){FILE *f=fopen(argv[2],"rb");if(!f){perror("file");return 2;}int c;while((c=fgetc(f))!=EOF)putchar(c);fclose(f);return 0;}
 if(argc>2 && !strcmp(argv[1],"exists")){struct stat s;printf("%d\n",stat(argv[2],&s)==0);return 0;}
 if(argc>2 && !strcmp(argv[1],"stat")){struct stat s;if(stat(argv[2],&s)){perror("stat");return 2;}printf("%o:%u:%u\n",s.st_mode&0777,s.st_uid,s.st_gid);return 0;}
 if(argc>2 && !strcmp(argv[1],"write")){FILE *f=fopen(argv[2],"wb");if(!f){perror("write");return 2;}fputs("persisted",f);fclose(f);puts("write-ok");return 0;}
 if(argc>1 && !strcmp(argv[1],"wait")){signal(SIGUSR1,handler);signal(SIGTERM,handler);puts("ready");fflush(stdout);while(!received)pause();printf("signal=%d\n",received);return 0;}
 char cwd[4096];if(!getcwd(cwd,sizeof(cwd)))return 2;
 printf("uid=%u\ngid=%u\ncwd=%s\nAPP_MODE=%s\nBUILD_ONLY=%s\n",getuid(),getgid(),cwd,getenv("APP_MODE")?getenv("APP_MODE"):"<unset>",getenv("BUILD_ONLY")?getenv("BUILD_ONLY"):"<unset>");
 return 0;
}'''

def execute(case):
    endpoint='tcp://127.0.0.1:2375'
    assert os.getenv('DOCKER_HOST')==endpoint,'select the dedicated Docker workspace; no host socket is supported'
    docker=['docker','--host',endpoint]
    submitted=pathlib.Path('Dockerfile').read_text(encoding='utf-8')
    assert len(submitted.encode())<=32768
    stages=[]
    logical=submitted.replace('\\\n',' ').splitlines()
    allowed={'FROM','COPY','ADD','ARG','ENV','WORKDIR','USER','CMD','ENTRYPOINT','LABEL','EXPOSE','STOPSIGNAL'}
    for line in logical:
        line=line.strip()
        if not line:continue
        if line.startswith('#'):
            assert not re.match(r'#\s*(syntax|escape)\s*=',line,re.I),'external Dockerfile frontends are outside this exercise'
            continue
        instruction=line.split(None,1)[0].upper()
        assert instruction in allowed,'only the documented scratch build instructions are supported; no RUN or ONBUILD'
        assert '://' not in line and 'git@' not in line,'no remote build inputs'
        if instruction=='FROM':
            parts=shlex.split(line)
            assert len(parts) in (2,4) and parts[1] in ['scratch',*stages],'only scratch or an already-defined local stage is permitted'
            if len(parts)==4:
                assert parts[2].upper()=='AS' and re.fullmatch('[a-z][a-z0-9_-]*',parts[3])
                stages.append(parts[3])
            else:stages.append(str(len(stages)))
        if instruction in ('COPY','ADD'):
            for source in re.findall(r'--from=([^\s]+)',line):
                assert source in stages or source.isdecimal() and int(source)<len(stages),'COPY --from cannot pull an external image'
    assert stages,'Dockerfile must define a local scratch stage'
    images=[];containers=[]
    def call(args,timeout=25):
        result=subprocess.run([*docker,*args],capture_output=True,text=True,timeout=timeout,env=dict(os.environ,DOCKER_BUILDKIT='1' if case['mode']=='chmod' else '0'))
        assert result.returncode==0,'native Docker command failed: '+(result.stdout+result.stderr)[-5000:]
        return result.stdout
    with tempfile.TemporaryDirectory(prefix='opsforge-dockerfile-',dir='/workspace') as temp:
        folder=pathlib.Path(temp);context=folder/'context';context.mkdir()
        (folder/'probe.c').write_text(PROBE,encoding='utf-8')
        subprocess.run(['gcc','-O2','-static',str(folder/'probe.c'),'-o',str(context/'probe')],check=True,capture_output=True,timeout=10)
        subprocess.run(['gcc','-O2',str(folder/'probe.c'),'-o',str(context/'probe-dynamic')],check=True,capture_output=True,timeout=10)
        (context/'probe-static').write_bytes((context/'probe').read_bytes());(context/'probe-static').chmod(0o755)
        marker='payload-'+secrets.token_hex(18)
        (context/'payload.txt').write_text(marker,encoding='utf-8')
        (context/'secret.txt').write_text('private-'+secrets.token_hex(18),encoding='utf-8')
        (context/'service/migrations').mkdir(parents=True)
        (context/'service/migrations/001.sql').write_text(marker,encoding='utf-8')
        with tarfile.open(context/'bundle.tar','w') as archive:
            data=marker.encode();info=tarfile.TarInfo('nested/payload.txt');info.size=len(data);info.mode=0o644;archive.addfile(info,io.BytesIO(data))
        (context/'Dockerfile').write_text(submitted,encoding='utf-8')
        if pathlib.Path('.dockerignore').exists():(context/'.dockerignore').write_text(pathlib.Path('.dockerignore').read_text(encoding='utf-8'),encoding='utf-8')
        def build(target=None,build_args=None):
            image='opsforge-exercise:'+secrets.token_hex(18);images.append(image)
            args=['build','--network','none','--pull=false','--no-cache','--memory','128m','-t',image]
            if target:args+=['--target',target]
            for key,value in (build_args or {}).items():args+=['--build-arg',key+'='+value]
            call([*args,str(context)],40)
            return image
        def run(image,args=None,env=None,readonly=True,entrypoint=None):
            name='opsforge-check-'+secrets.token_hex(12);containers.append(name)
            command=['run','--name',name,'--rm','--network','none','--cap-drop','ALL','--security-opt','no-new-privileges','--memory','64m','--cpus','.25','--pids-limit','32']
            if readonly:command+=['--read-only']
            if entrypoint:command+=['--entrypoint',entrypoint]
            for key,value in (env or {}).items():command+=['--env',key+'='+value]
            return call([*command,image,*(args or [])]).strip()
        def config(image):return json.loads(call(['image','inspect',image]))[0]['Config']
        def probe(image,*args):return run(image,list(args),entrypoint='/probe')
        try:
            mode=case['mode'];build_args={'APP_MODE':marker} if mode=='arg' else None
            image=build(build_args=build_args)
            if mode=='workdir':assert run(image)==marker and 'cwd=/app' in probe(image,'summary')
            elif mode=='env':
                assert 'APP_MODE=production' in run(image) and 'APP_MODE=staging' in run(image,env={'APP_MODE':'staging'})
            elif mode=='user':assert 'uid=10001\ngid=10002\n' in run(image)
            elif mode=='argv':assert run(image)=='ARG_1=--name\nARG_2=value with spaces'
            elif mode=='literal':assert run(image)=='ARG_1=$HOME'
            elif mode=='arg':assert 'APP_MODE='+marker in run(image) and 'BUILD_ONLY=<unset>' in run(image)
            elif mode=='label':
                assert config(image).get('Labels',{}).get('org.opencontainers.image.source')=='opsforge-training'
                assert config(image).get('Labels',{}).get('org.opencontainers.image.version')=='1.2.3'
                assert 'uid=' in run(image)
            elif mode=='ignore':assert probe(image,'file','/data/payload.txt')==marker and probe(image,'exists','/data/secret.txt')=='0'
            elif mode=='chown':assert probe(image,'stat','/data/payload.txt')=='644:10001:10002' and probe(image,'file','/data/payload.txt')==marker
            elif mode=='chmod':assert probe(image,'stat','/probe').startswith('555:') and 'uid=' in run(image)
            elif mode=='lastcmd':assert run(image)=='ARG_1=live'
            elif mode=='entrypoint':assert run(image)=='ARG_1=default' and run(image,['override','two words'])=='ARG_1=override\nARG_2=two words'
            elif mode=='multistage':assert 'uid=' in run(image) and probe(image,'exists','/build/secret.txt')=='0' and probe(image,'exists','/secret.txt')=='0'
            elif mode=='target':assert run(image)=='ARG_1=release' and run(build(target='debug'))=='ARG_1=debug'
            elif mode=='stop':
                name='opsforge-stop-'+secrets.token_hex(12);containers.append(name)
                call(['run','-d','--name',name,'--network','none','--cap-drop','ALL','--security-opt','no-new-privileges','--memory','64m','--cpus','.25','--pids-limit','32','--read-only',image])
                for _ in range(30):
                    if 'ready' in call(['logs',name]):break
                    time.sleep(.1)
                call(['stop','--time','3',name]);assert 'signal=10' in call(['logs',name])
                assert json.loads(call(['inspect',name]))[0]['State']['ExitCode']==0
            elif mode=='writable':assert run(image,readonly=False)=='write-ok' and 'uid=10001' in probe(image,'summary')
            elif mode=='copyfrom':
                output=run(image);assert 'uid=0\ngid=0\ncwd=/\nAPP_MODE=<unset>' in output
                assert probe(image,'exists','/build/secret.txt')=='0'
            elif mode=='migrations':assert probe(image,'file','/app/service/migrations/001.sql')==marker and probe(image,'exists','/app/secret.txt')=='0'
            elif mode=='static':assert 'uid=' in run(image)
            elif mode=='expose':
                assert '8080/tcp' in (config(image).get('ExposedPorts') or {})
                name='opsforge-port-'+secrets.token_hex(12);containers.append(name);call(['create','--name',name,'--network','none',image])
                assert not json.loads(call(['inspect',name]))[0]['HostConfig'].get('PortBindings')
                assert 'uid=' in run(image)
            elif mode=='addtar':assert probe(image,'file','/data/nested/payload.txt')==marker
            else:raise AssertionError('unknown reviewed Dockerfile exercise')
            print('NATIVE_DOCKERFILE_ASSERTIONS_PASSED',mode)
        finally:
            for name in containers:subprocess.run([*docker,'rm','-f',name],capture_output=True,timeout=10)
            for image in images:subprocess.run([*docker,'image','rm','-f',image],capture_output=True,timeout=10)

