    for line in logical:
        line=line.strip()
        if not line:continue
        if line.startswith('#'):
            assert not re.match(r'#\s*(syntax|escape)\s*=',line,re.I),'external Dockerfile frontends are outside this exercise'
            continue
        instruction=line.split(None,1)[0].upper()
        assert instruction in allowed,'only the documented scratch build instructions are supported; no RUN or ONBUILD'
        assert '://' not in line and 'git@' not in line,'no remote build inputs'
        if instruction=='FROM':
            parts=shlex.split(line)
