PROBE = r'''#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <signal.h>
volatile sig_atomic_t received=0;
static void handler(int value){received=value;}
int main(int argc,char **argv){
 if(argc>1 && !strcmp(argv[1],"args")){for(int i=2;i<argc;i++)printf("ARG_%d=%s\n",i-1,argv[i]);return 0;}
 if(argc>2 && !strcmp(argv[1],"file")){FILE *f=fopen(argv[2],"rb");if(!f){perror("file");return 2;}int c;while((c=fgetc(f))!=EOF)putchar(c);fclose(f);return 0;}
 if(argc>2 && !strcmp(argv[1],"exists")){struct stat s;printf("%d\n",stat(argv[2],&s)==0);return 0;}
 if(argc>2 && !strcmp(argv[1],"stat")){struct stat s;if(stat(argv[2],&s)){perror("stat");return 2;}printf("%o:%u:%u\n",s.st_mode&0777,s.st_uid,s.st_gid);return 0;}
 if(argc>2 && !strcmp(argv[1],"write")){FILE *f=fopen(argv[2],"wb");if(!f){perror("write");return 2;}fputs("persisted",f);fclose(f);puts("write-ok");return 0;}
 if(argc>1 && !strcmp(argv[1],"wait")){signal(SIGUSR1,handler);signal(SIGTERM,handler);puts("ready");fflush(stdout);while(!received)pause();printf("signal=%d\n",received);return 0;}
 char cwd[4096];if(!getcwd(cwd,sizeof(cwd)))return 2;
 printf("uid=%u\ngid=%u\ncwd=%s\nAPP_MODE=%s\nBUILD_ONLY=%s\n",getuid(),getgid(),cwd,getenv("APP_MODE")?getenv("APP_MODE"):"<unset>",getenv("BUILD_ONLY")?getenv("BUILD_ONLY"):"<unset>");
 return 0;
}'''

